// Stage 2 data (desert ruins), generated by tools/stage2_to_level.py from the NES map rip.
import terrain from './terrain.txt?raw';
import data from './entities.json';

// Placed by hand on top of the NES map's entities (NES pixels: x = metres / 0.15625 + 256, y = metres / 0.15625 + 2872),
// kept here so regenerating entities.json doesn't lose them. Appended last, so older saved games still line up.
const EXTRA = [
  { type: 'lighttank', x: 307, y: 1554 }, // x 8, z -206: on the terrace north of the middle turret
  { type: 'mediumtank', x: 303, y: 939 }, // x 7.4, z -302: on the grass a little north of the turret at x 2.5
  { type: 'enemyjeep', x: 172, y: 755 }, // x -13.2, z -330.8: circles the jeep lobbing bombs (enemy-jeeps.js)
  { type: 'enemyjeep', x: 362, y: 654 }, // x 16.5, z -346.5
  { type: 'enemyjeep', x: 256, y: 370 }, // x 0, z -391: on the causeway at the arena's mouth
];

export default {
  name: 'Stage 2', music: 'requiem',
  number: 2,
  terrain: terrain.trim().split('\n').map(r => r.trim()),
  entities: [...data.entities, ...EXTRA],
  meta: data.meta,
  // Look: pale desert sand, scrub grass in the old field, sandstone ruins. (See THEMES in world.js.)
  theme: 'ruins',
  leanSlopes: 1, // the jeep tips a little, nose up as it climbs the stairs and down as it comes off them (visual only)
  edgeMargin: 2.5, // the colonnades along both sides are the edge of play (their gaps don't lead out)
  // pillars that break as the jeep comes up to the trigger: the top falls south (or `roll` degrees off
  // south, + toward the east) and rolls on (toppling.js)
  toppling: [
    { x: -7.5, z: -241.4, breakAt: 3, trigger: { x0: -12, x1: 10, z: -226 } }, // over the pillar in front of it; goes as the jeep comes off the ramp from the east terrace (its foot is at x 10)
    { x: -7.5, z: -308.9, breakAt: 2.2, trigger: { x: -7.5, z: -286 } }, // early: a jeep rushing on meets the top as it comes down and rolls
    { x: -17.5, z: -328.9, breakAt: 2.5, trigger: { x: -16.3, z: -308.8 } },
    { x: 2.5, z: -328.9, breakAt: 2.5, trigger: [{ x: -7.2, z: -312.3, r: 6 }, { x: 12.1, z: -312.3, r: 6 }] }, // (the jeep coming up either side)
    { x: 12.5, z: -333.9, breakAt: 2.5, roll: 20, trigger: { x: 18.8, z: -318.4, r: 6 } }, // rolls off a little toward the south-east
    { x: 22.5, z: -341.4, breakAt: 2.5, roll: -20, trigger: { x: 18.9, z: -322.3, r: 6 } }, // rolls off a little toward the south-west
    { x: -7.5, z: -341.4, breakAt: 2.5, aim: true, trigger: { near: 20 } }, // goes when the jeep comes within 20 m, from any side, and falls toward it
  ],
  // bombers that dive on the jeep (bomber-raid.js), each once: as it comes up to z (or `ahead` m short of it), from the
  // top-right corner (from: 'nw': the top-left; 'e': the right-hand side)
  bomber: [
    { x: -29, z: -189 }, // on the terrace inside the west colonnade
    { z: -328, ahead: 0, from: 'nw' }, // crossing z -328, along with the enemy jeep below
    { z: -365, ahead: 0, from: 'e' }, // crossing z -365, in from the east
  ],
  // enemy jeeps brought in by the script: one appears at (x, z), already driving, as the jeep comes north to trigger.z
  jeepSpawns: [
    { x: -17, z: -300, trigger: { z: -328 } }, // well behind the jeep as it crosses z -328 (with a bomber)
  ],
  boss: 'statues', // the four sandstone busts at the top of the arena fire missiles (arena.js, statues.js)
  difficulty: { // (how often soldiers fire goes by the stage number: soldierFire in soldiers.js)
    soldier: {
      wander: .7,
      wanderEvery: [1.5, 3],
    },
  },
};
